      border-radius: var(--radius);
      box-shadow: var(--shadow);
      overflow: clip;
    }

    .card-hero {
      padding: 2rem 2rem 1rem;
      background:
        linear-gradient(135deg, rgba(37, 99, 235, 0.1), rgba(124, 58, 237, 0.08)),
