      width: 100%;
      border: 1.5px solid var(--border);
      border-radius: var(--radius-sm);
      padding: 0.9rem 1rem;
      font: inherit;
      color: var(--text);
      background: var(--surface);
      transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
