</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const state = {
      values: {
        fullName: '',
        email: '',
        phone: ''
      },
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      submitted: false,
      status: '',
      focusAfterRender: null
    };

    const fieldConfig = [
      {
        id: 'fullName',
        label: 'Full name',
        type: 'text',
        required: true,
        autocomplete: 'name',
        placeholder: 'Jane Doe'
      },
      {
        id: 'email',
        label: 'Email address',
        type: 'email',
        required: true,
        autocomplete: 'email',
        placeholder: 'jane@example.com'
      },
      {
        id: 'phone',
        label: 'Phone number',
        type: 'tel',
        required: false,
        autocomplete: 'tel',
        placeholder: '+1 (555) 123-4567',
        hint: 'Optional. Use digits, spaces, parentheses, dashes, or a leading +, for example +1 (555) 123-4567.'
      }
    ];

    function escapeHtml(value) {
      return String(value)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#39;');
    }

    function validateFullName(value) {
      if (!value.trim()) {
        return 'Full name is required.';
      }
      return '';
    }

    function validateEmail(value) {
      const trimmed = value.trim();
      if (!trimmed) {
        return 'Email address is required.';
      }
      const pattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!pattern.test(trimmed)) {
        return 'Enter a valid email address.';
      }
      return '';
    }

    function validatePhone(value) {
      const trimmed = value.trim();
      if (!trimmed) {
        return '';
      }
      if (!/^\+?[0-9\s().-]+$/.test(trimmed)) {
        return 'Use a phone number with digits and standard separators only.';
      }
      const digitCount = (trimmed.match(/\d/g) || []).length;
      if (digitCount < 7 || digitCount > 15) {
        return 'Enter a valid phone number with 7 to 15 digits.';
      }
      return '';
    }

    function getErrors(values) {
      return {
        fullName: validateFullName(values.fullName),
        email: validateEmail(values.email),
        phone: validatePhone(values.phone)
      };
    }

    function shouldShowError(id, errors) {
      return state.submitted || state.touched[id] || Boolean(errors[id]);
    }

    function fieldMarkup(config, errors) {
      const { id, label, type, required, autocomplete, placeholder, hint } = config;
      const error = errors[id];
      const showError = shouldShowError(id, errors) && error;
      const describedBy = [hint ? `${id}-hint` : '', `${id}-error`].filter(Boolean).join(' ');
      return `
        <div class="form-field" data-invalid="${showError ? 'true' : 'false'}">
          <label for="${id}">
            ${escapeHtml(label)}${required ? ' <span class="required" aria-hidden="true">*</span>' : ''}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            autocomplete="${autocomplete}"
            placeholder="${escapeHtml(placeholder)}"
            value="${escapeHtml(state.values[id])}"
            ${required ? 'required aria-required="true"' : ''}
            ${showError ? 'aria-invalid="true"' : 'aria-invalid="false"'}
            aria-describedby="${describedBy}"
          />
          ${hint ? `<p class="hint" id="${id}-hint">${escapeHtml(hint)}</p>` : ''}
          <p class="field-error" id="${id}-error" aria-live="polite">${showError ? escapeHtml(error) : ''}</p>
        </div>
      `;
    }

    function appMarkup(errors) {
      return `
        <div class="page-shell">
          <header aria-label="Support page header">
            <div class="brand">
              <div class="brand-mark" aria-hidden="true"></div>
              <span>Northstar Support</span>
            </div>
          </header>

          <main id="main-content">
            <section class="support-card" aria-labelledby="support-title">
              <div class="card-hero">
                <h1 id="support-title">Contact support</h1>
                <p class="lede">Send us your details and we&apos;ll route your request to the right team.</p>
              </div>

              <div class="form-wrap">
                <p class="status" id="form-status" role="status" aria-live="polite">${escapeHtml(state.status)}</p>
                <form id="support-form" novalidate>
                  ${fieldMarkup(fieldConfig[0], errors)}
                  ${fieldMarkup(fieldConfig[1], errors)}
                  ${fieldMarkup(fieldConfig[2], errors)}
                  <div class="actions">
                    <button type="submit">Submit request</button>
                  </div>
                </form>
              </div>
            </section>
          </main>

          <footer>
            We&apos;ll only use this information to respond to your support request.
          </footer>
        </div>
      `;
    }

    function attachHandlers() {
      const form = document.getElementById('support-form');
      const inputs = ['fullName', 'email', 'phone']
        .map((id) => document.getElementById(id))
        .filter(Boolean);

      inputs.forEach((input) => {
        input.addEventListener('input', (event) => {
          state.values[event.target.name] = event.target.value;
          if (state.submitted || state.touched[event.target.name]) {
            state.touched[event.target.name] = true;
            render();
          }
        });

        input.addEventListener('blur', (event) => {
          state.touched[event.target.name] = true;
          render();
        });
      });

      form.addEventListener('submit', (event) => {
        event.preventDefault();
        state.submitted = true;

        const errors = getErrors(state.values);
        const firstInvalid = fieldConfig.find((config) => errors[config.id]);

        if (firstInvalid) {
          state.status = 'Please fix the highlighted fields.';
          state.focusAfterRender = firstInvalid.id;
          render();
          return;
        }

        state.status = 'Thanks — your request is ready to submit.';
        render();
      });
    }

    function render() {
      const errors = getErrors(state.values);
      document.getElementById('app').innerHTML = appMarkup(errors);
      attachHandlers();

      if (state.focusAfterRender) {
        const next = document.getElementById(state.focusAfterRender);
        state.focusAfterRender = null;
        if (next) {
          next.focus();
        }
      }
    }

    render();
  </script>
