<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const state = {
      values: {
        fullName: '',
        email: '',
        phone: ''
      },
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      submitted: false,
      status: '',
      focusAfterRender: null
